{
  "probability": 0.92,
  "range_low": 0.85,
  "range_high": 0.97,
  "summary": [
    "Early-2026 pace through February (~606 deaths/missing by Feb 24) strongly supports the likelihood that 1,000+ Mediterranean deaths could be recorded by May if the pace persists.",
    "Historical base rates for Mediterranean fatalities (roughly 2,100–2,450 annually) make hitting 1,000 by May plausible within the year’s scale.",
    "Central Mediterranean route risk and seasonal patterns add upward pressure, while SAR/policy dynamics and possible weather effects introduce both dampening and risk.",
    "Calibrated posterior: 92% probability with a 0.85–0.97 uncertainty range, acknowledging reporting lags and potential interventions as sources of residual uncertainty."
  ],
  "confidence": "high",
  "narrative": "The unusually high early-2026 fatality pace, combined with historical annual totals, yields a high but not guaranteed chance of reaching 1,000 deaths by May. The estimate centers around a 92% posterior probability, with some uncertainty due to reporting delays and potential policy/SAR changes.",
  "justification": {
    "anchor": {
      "probability": 0.85,
      "basis": "Reference class: annual Mediterranean migrant fatalities tracked by IOM Missing Migrants Project; anchor probability drawn from early-2026 counts (≈606 by February) and typical seasonal expectations, providing a starting point for updates."
    },
    "factor_updates": [
      {
        "factor": "Early-2026 pace through February",
        "direction": "up",
        "magnitude": "strong",
        "rationale": "606 deaths/missing by Feb 24 implies momentum toward 1,000 by May if sustained into March–April."
      },
      {
        "factor": "Historical base-rate for Mediterranean fatalities",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Annual totals around 2,100–2,450; sustained high pace makes 1,000 by May plausible within yearly scale."
      },
      {
        "factor": "Central Mediterranean route risk / seasonal pattern",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Central Mediterranean remains deadliest; ongoing fatalities in late winter–spring raise odds of reaching 1,000 by May."
      },
      {
        "factor": "Policy/SAR dynamics (crackdowns vs rescue capacity)",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Stronger controls or reduced SAR could dampen fatalities, lowering likelihood of hitting 1,000 by May."
      },
      {
        "factor": "Reporting lags / data revisions",
        "direction": "neutral",
        "magnitude": "weak",
        "rationale": "Counts can be revised; early-year totals may undercount, adding uncertainty to May totals."
      },
      {
        "factor": "Adverse weather / sea conditions",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Storms or rough seas could increase fatalities, pushing totals higher than currently observed."
      }
    ],
    "synthesis_rationale": "Starting from an 0.85 anchor, multiple upward pressures from pace, base-rate, and seasonal risk were applied, with modest downward pressure from policy/SAR dynamics and weak downward/upward effects from reporting lags and weather. The aggregation yields a posterior around 0.92, with a calibrated range reflecting residual uncertainty due to data lags and potential shifts in SAR policy or conditions."
  }
}

